/**
 * Qoder Agent SDK
 *
 * TypeScript SDK for programmatic access to qodercli capabilities.
 *
 * The SDK talks to the configured Qoder runtime transport using a
 * bidirectional JSON line protocol.
 *
 * @example Basic usage
 * ```typescript
 * import { query } from 'qoder-agent-sdk';
 *
 * for await (const message of query({ prompt: 'Hello, Qoder!' })) {
 *   console.log(message);
 * }
 * ```
 *
 * @example Multi-turn conversation
 * ```typescript
 * import { query } from 'qoder-agent-sdk';
 *
 * async function* userMessages() {
 *   yield { type: 'user', message: { role: 'user', content: 'Hello' }, parent_tool_use_id: null };
 *   // ... yield more messages
 * }
 *
 * for await (const message of query({ prompt: userMessages(), options: { model: 'performance' } })) {
 *   console.log(message);
 * }
 * ```
 *
 * @example With MCP server
 * ```typescript
 * import { query, createSdkMcpServer, tool } from 'qoder-agent-sdk';
 * import { z } from 'zod/v4';
 *
 * const server = createSdkMcpServer({
 *   name: 'my-tools',
 *   tools: [
 *     tool('greet', 'Say hello', { name: z.string() }, async (args) => ({
 *       content: [{ type: 'text', text: `Hello, ${args.name}!` }]
 *     }))
 *   ]
 * });
 *
 * for await (const msg of query({
 *   prompt: 'Use the greet tool to say hi to Alice',
 *   options: { mcpServers: { 'my-tools': server } }
 * })) {
 *   console.log(msg);
 * }
 * ```
 */
